//! runtime_dlls.rs
//!
//! Single-File Portable Runtime DLL Bootstrap for Pulex (Windows x64)
//! - Embeds gzip-compressed `duckdb.dll` and `WebView2Loader.dll` generated by `build.rs`.
//! - On startup (before DuckDB or WebView2 delay-loaded imports are resolved), extracts any
//!   missing or size-mismatched DLL into `pulexAppData_<id>/bin/` (or `%TEMP%/pulex_runtime_<ver>/`
//!   if the portable directory is read-only) using atomic temp-file renames.
//! - Registers the runtime `bin/` directory with Windows via `SetDllDirectoryW`.

use flate2::read::GzDecoder;
use std::fs::{self, File};
use std::io::{self, BufWriter};
use std::path::{Path, PathBuf};

include!(concat!(env!("OUT_DIR"), "/embedded_dll_meta.rs"));

static DUCKDB_DLL_GZ: &[u8] = include_bytes!(concat!(env!("OUT_DIR"), "/duckdb.dll.gz"));
static WEBVIEW2_DLL_GZ: &[u8] = include_bytes!(concat!(env!("OUT_DIR"), "/WebView2Loader.dll.gz"));

#[cfg(windows)]
#[link(name = "kernel32")]
extern "system" {
    fn SetDllDirectoryW(lpPathName: *const u16) -> i32;
}

/// Register a directory in the Windows DLL search order for delay-loaded imports.
fn register_dll_directory(dir: &Path) -> Result<(), String> {
    #[cfg(windows)]
    {
        use std::os::windows::ffi::OsStrExt;
        let wide: Vec<u16> = dir
            .as_os_str()
            .encode_wide()
            .chain(std::iter::once(0))
            .collect();
        let ok = unsafe { SetDllDirectoryW(wide.as_ptr()) };
        if ok == 0 {
            return Err(format!(
                "SetDllDirectoryW failed for {} (OS error: {})",
                dir.display(),
                io::Error::last_os_error()
            ));
        }
    }
    #[cfg(not(windows))]
    {
        let _ = dir;
    }
    Ok(())
}

/// Check if a directory can be created and written to.
fn ensure_writable_dir(dir: &Path) -> bool {
    if fs::create_dir_all(dir).is_err() {
        return false;
    }
    let probe = dir.join(format!(".write_probe_{}", std::process::id()));
    match File::create(&probe) {
        Ok(_) => {
            let _ = fs::remove_file(&probe);
            true
        }
        Err(_) => false,
    }
}

/// Resolve the runtime DLL extraction directory: prefers `app_data_dir/bin`,
/// falling back to `%TEMP%/pulex_runtime_<version>` if `app_data_dir` is read-only.
pub fn resolve_runtime_bin_dir(app_data_dir: &Path) -> Result<PathBuf, String> {
    let primary = app_data_dir.join("bin");
    if ensure_writable_dir(&primary) {
        return Ok(primary);
    }

    let fallback = std::env::temp_dir().join(format!("pulex_runtime_{}", env!("CARGO_PKG_VERSION")));
    if ensure_writable_dir(&fallback) {
        return Ok(fallback);
    }

    Err(format!(
        "Unable to create writable runtime DLL directory at {} or {}",
        primary.display(),
        fallback.display()
    ))
}

/// Extract a single gzip-compressed DLL payload into `bin_dir/dll_name` if missing or size-mismatched.
/// Uses a PID-scoped temporary file + atomic rename so concurrent launches never see partial DLLs.
pub fn extract_dll_if_needed(
    bin_dir: &Path,
    dll_name: &str,
    gz_bytes: &[u8],
    expected_len: u64,
) -> Result<PathBuf, String> {
    let target_path = bin_dir.join(dll_name);
    if gz_bytes.is_empty() || expected_len == 0 {
        return Ok(target_path);
    }

    if let Ok(meta) = fs::metadata(&target_path) {
        if meta.len() == expected_len {
            return Ok(target_path);
        }
    }

    let tmp_path = bin_dir.join(format!("{}.tmp.{}", dll_name, std::process::id()));
    {
        let mut decoder = GzDecoder::new(gz_bytes);
        let out_file = File::create(&tmp_path)
            .map_err(|e| format!("Failed to create temp DLL {}: {}", tmp_path.display(), e))?;
        let mut writer = BufWriter::with_capacity(256 * 1024, out_file);
        io::copy(&mut decoder, &mut writer)
            .map_err(|e| format!("Failed to decompress {}: {}", dll_name, e))?;
        io::Write::flush(&mut writer)
            .map_err(|e| format!("Failed to flush {}: {}", dll_name, e))?;
    }

    if let Err(rename_err) = fs::rename(&tmp_path, &target_path) {
        // Another instance may have extracted and locked the exact same DLL concurrently
        let _ = fs::remove_file(&tmp_path);
        if let Ok(meta) = fs::metadata(&target_path) {
            if meta.len() == expected_len {
                return Ok(target_path);
            }
        }
        return Err(format!(
            "Failed to finalize runtime DLL {} ({})",
            target_path.display(),
            rename_err
        ));
    }

    Ok(target_path)
}

/// Ensure embedded `duckdb.dll` and `WebView2Loader.dll` are extracted and registered
/// in Windows' DLL search path before any delay-loaded symbol is invoked.
pub fn ensure_runtime_dlls_loaded(app_data_dir: &Path) -> Result<PathBuf, String> {
    let bin_dir = resolve_runtime_bin_dir(app_data_dir)?;
    extract_dll_if_needed(&bin_dir, "duckdb.dll", DUCKDB_DLL_GZ, DUCKDB_DLL_LEN)?;
    extract_dll_if_needed(&bin_dir, "WebView2Loader.dll", WEBVIEW2_DLL_GZ, WEBVIEW2_DLL_LEN)?;
    register_dll_directory(&bin_dir)?;
    Ok(bin_dir)
}

#[cfg(test)]
mod tests {
    use super::*;
    use flate2::write::GzEncoder;
    use flate2::Compression;
    use std::io::Write;

    #[test]
    fn test_extract_single_dll_gzip_and_idempotency() {
        let tmp = std::env::temp_dir().join("pulex_runtime_dll_unit_test");
        let _ = fs::remove_dir_all(&tmp);
        fs::create_dir_all(&tmp).unwrap();

        let payload = b"MZ_SYNTHETIC_DLL_PAYLOAD_FOR_PULEX_TEST_1234567890";
        let mut enc = GzEncoder::new(Vec::new(), Compression::best());
        enc.write_all(payload).unwrap();
        let gz = enc.finish().unwrap();

        let out = extract_dll_if_needed(&tmp, "synthetic.dll", &gz, payload.len() as u64).unwrap();
        assert!(out.is_file());
        assert_eq!(fs::read(&out).unwrap(), payload);

        // Second call should hit fast-path idempotency without error
        let out2 = extract_dll_if_needed(&tmp, "synthetic.dll", &gz, payload.len() as u64).unwrap();
        assert_eq!(out, out2);

        let _ = fs::remove_dir_all(&tmp);
    }

    #[test]
    fn test_embedded_runtime_dlls_extract_cleanly() {
        let tmp = std::env::temp_dir().join("pulex_embedded_dll_extract_test");
        let _ = fs::remove_dir_all(&tmp);
        let bin_dir = resolve_runtime_bin_dir(&tmp).unwrap();
        if DUCKDB_DLL_LEN > 0 {
            let p = extract_dll_if_needed(&bin_dir, "duckdb.dll", DUCKDB_DLL_GZ, DUCKDB_DLL_LEN).unwrap();
            assert_eq!(fs::metadata(&p).unwrap().len(), DUCKDB_DLL_LEN);
        }
        if WEBVIEW2_DLL_LEN > 0 {
            let p = extract_dll_if_needed(&bin_dir, "WebView2Loader.dll", WEBVIEW2_DLL_GZ, WEBVIEW2_DLL_LEN).unwrap();
            assert_eq!(fs::metadata(&p).unwrap().len(), WEBVIEW2_DLL_LEN);
        }
        let _ = fs::remove_dir_all(&tmp);
    }
}
